// DRY-RUN MODE: Simulate preflight without SSH
// No real SSH commands executed

return [{
  json: {
    preflight_ok: true,
    opencode_ready: true,
    provider_ready: true,
    runner_hostname: 'lxc-dev-runner (SIMULATED)',
    dry_run: true,
    ssh_preflight_apply: $json.ssh_preflight_apply,
    blueprint_present: $json.blueprint_present,
    project_creation_apply: $json.project_creation_apply,
    speckit_init_apply: $json.speckit_init_apply,
    opencode_build_apply: $json.opencode_build_apply,
    raw_output_safe_length: 0,
    preflight_mode: 'DRY_RUN_SIMULATED'
  }
}];

const stdout = String($json.stdout || '');
const hasOpenCode = /\d+\.\d+\.\d+/.test(stdout.match(/opencode.*?((?:\d+\.){2}\d+)/)?.[1] || '');
const hasProviderEnv = stdout.includes('provider_env: EXISTS') || stdout.includes('PROVIDER_ENV: EXISTS');
const preflightOk = stdout.includes('PREFlight_COMPLETE');

return [{
  json: {
    preflight_ok: preflightOk,
    opencode_ready: hasOpenCode,
    provider_ready: hasProviderEnv,
    runner_hostname: (stdout.match(/HOST[=: ]*([^\n]+)/) || ['','unknown'])[1].trim(),
    dry_run: $json.dry_run,
    blueprint_present: $json.blueprint_present,
    project_creation_apply: $json.project_creation_apply,
    speckit_init_apply: $json.speckit_init_apply,
    opencode_build_apply: $json.opencode_build_apply,
    raw_output_safe_length: stdout.length,
    preflight_mode: 'REAL_SSH'
  }
}];

const slug = $json.project_slug;
const rootDir = '/home/runner/SpecKit_Projects';

// DRY-RUN: Only compute paths, do NOT create anything
return [{
  json: {
    ...$json,
    project_root: rootDir,
    project_dir: `${rootDir}/${slug}`,
    create_dir_cmd: `mkdir -p ${rootDir}/${slug}/{docs/blueprint,evidence} && echo 'PROJECT_DIR_CREATED' || echo 'PROJECT_DIR_FAILED'`,
    dry_run_path_computed: true,
    message: `DRY RUN: Would create ${rootDir}/${slug} but project_creation_apply=false. Path computed only.`
  }
}];

// Dry-run: project creation not applied. Stop here safely.
return [{
  json: {
    ...$json,
    status: 'DRY_RUN_COMPLETE',
    message: `Blueprint validated. Project dir would be: ${$json.project_dir}. No folder created (project_creation_apply=false).`,
    project_dir_computed: $json.project_dir,
    project_created: false,
    next_safe_step: 'Set project_creation_apply=true to create project folder'
  }
}];

return [{
  json: {
    status: 'RUNNER_NOT_READY',
    message: 'Preflight checks failed. Check runner SSH, OpenCode, and provider env.',
    preflight_result: $json
  }
}];

// WAIT_FOR_BLUEPRINT Gate (dry-run compatible)
// In dry-run mode with blueprint_present=false, this is the target stop point.
// In real mode, this waits for a webhook callback with blueprint data.

if ($json.dry_run === true && $json.blueprint_present === false) {
  // MODE A: No blueprint, stop here
  return [{
    json: {
      status: 'WAIT_FOR_BLUEPRINT',
      gate_reached: true,
      message: 'Workflow reached WAIT_FOR_BLUEPRINT gate. No blueprint provided. Stopping safely.',
      dry_run: true,
      blueprint_present: false,
      timestamp: new Date().toISOString()
    }
  }];
}

// In dry-run mode with blueprint_present=true, pass through to validation
if ($json.dry_run === true && $json.blueprint_present === true) {
  // MODE B: Blueprint present, continue to validation
  return [{
    json: {
      ...$json,
      status: 'WAIT_FOR_BLUEPRINT',
      gate_reached: true,
      message: 'Workflow passed WAIT_FOR_BLUEPRINT gate. Blueprint present, proceeding to validation.',
      // Test blueprint data for dry-run
      body: {
        blueprint: 'Mini Task Tracker - A minimal task management application\n\nGoal: Create a simple task tracker with CRUD operations.\n\nFeatures:\n- Create tasks with title and description\n- List all tasks\n- Mark tasks as complete\n- Delete tasks\n\nExpected Outcome: A working CLI-based task tracker.\n\nRequirements:\n- Python 3.10+\n- SQLite database\n- Command-line interface\n\nAcceptance Criteria:\n- User can add a task\n- User can list all tasks\n- User can mark a task as done\n- User can delete a task'
      }
    }
  }];
}

// Real mode: pass through to WAIT node (original behavior)
return [$json];

const blueprint = String($json.body?.blueprint || $json.blueprint || $json.body || '').trim();

// Secret detection
const secretPatterns = [
  /sk-[A-Za-z0-9]{20,}/,
  /ghp_[A-Za-z0-9_]{20,}/,
  /github_pat_[A-Za-z0-9_]{20,}/,
  /Bearer\s+[A-Za-z0-9._\-]{20,}/,
  /-----BEGIN\s+[A-Z\s]+PRIVATE\s+KEY-----/,
  /eyJ[A-Za-z0-9_\-]{50,}/,
  /api_key\s*[=:]\s*[A-Za-z0-9]{20,}/i
];

const hasSecret = secretPatterns.some(p => p.test(blueprint));

// Content validation
const hasGoal = /(?:goal|ziel|problem|purpose|intent|objective)/i.test(blueprint);
const hasFunction = /(?:function|feature|software|application|app|program|tool|service|system)/i.test(blueprint);
const hasOutcome = /(?:outcome|result|expect|deliver|output|success)/i.test(blueprint);
const hasRequirements = /(?:requirement|story|need|must|should|shall|user|acceptance)/i.test(blueprint);
const contentLength = blueprint.length;
const contentSections = [hasGoal, hasFunction, hasOutcome, hasRequirements].filter(Boolean).length;

let status = 'BLUEPRINT_VALID';
if (hasSecret) status = 'RED_BLUEPRINT_SECRET';
else if (contentLength < 100) status = 'BLUEPRINT_EMPTY';
else if (contentSections < 3) status = 'BLUEPRINT_INCOMPLETE';
else if (contentSections < 5) status = 'BLUEPRINT_PARTIAL';

// Derive project slug
const firstLine = blueprint.split('\n')[0].replace(/^#+\s*/, '').trim();
const slug = firstLine
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '')
  .slice(0, 50) || 'blueprint-project';

return [{
  json: {
    ...$json,
    status: status,
    project_slug: slug,
    blueprint_length: contentLength,
    sections_found: contentSections,
    has_secret: hasSecret,
    blueprint_content: status === 'RED_BLUEPRINT_SECRET' ? '[REDACTED - SECRETS DETECTED]' : blueprint
  }
}];

return [{
  json: {
    status: $json.status,
    message: `Blueprint validation failed: ${$json.status}`,
    error: $json.status === 'RED_BLUEPRINT_SECRET' ? 'Secrets detected in blueprint. STOP.' : 'Blueprint incomplete. Resubmit with more detail.'
  }
}];

return [{
  json: {
    status: 'PIPELINE_COMPLETE',
    project_dir: $json.project_dir,
    project_slug: $json.project_slug,
    phases_completed: [
      'Runner Preflight',
      'WAIT_FOR_BLUEPRINT',
      'Blueprint Validation',
      'Project Folder Creation',
      'Spec Kit Init',
      'Git Init',
      'OpenCode Setup'
    ],
    next_steps: 'Run OpenCode Speckit phases in project directory',
    issue: '#19',
    timestamp: new Date().toISOString()
  }
}];
